{
  "reply": "利用二倍角公式，原方程化为 2sin(x)cos(x)=cos(x)，即 cos(x)(2sin(x)−1)=0。因此 cos(x)=0 或 sin(x)=1/2。在 0≤x<2π 内，解为 x=π/6、π/2、5π/6、3π/2。注意不能直接约去 cos(x)，否则会漏解。",
  "result": {
    "status": "solved",
    "problem": {
      "statement": "在 0≤x<2π 内解 sin(2x)=cos(x)。",
      "topic": "三角方程",
      "subtopics": ["正弦二倍角公式", "因式分解", "区间内的三角方程求解"],
      "givens": ["sin(2x)=cos(x)"],
      "variables": ["x：以弧度为单位的实数"],
      "constraints": ["0≤x<2π"],
      "goal": "求指定区间内方程的全部解。",
      "requested_method": null,
      "ambiguities": [],
      "assumptions": []
    },
    "plan": {
      "main_idea": "利用二倍角公式将方程化为乘积为零，分类求解。",
      "method": "二倍角公式与因式分解法",
      "prerequisites": ["sin(2x)=2sin(x)cos(x)", "两因式乘积为零时至少一个因式为零", "特殊角的三角函数值"],
      "steps": ["展开 sin(2x)，移项并提取公因式。", "分别求解 cos(x)=0 和 sin(x)=1/2。", "筛选区间内的解并代回原方程。"]
    },
    "solution": {
      "derivation": [
        {
          "step": 1,
          "expression": "sin(2x)=cos(x) ⇔ 2sin(x)cos(x)−cos(x)=0",
          "justification": "使用正弦二倍角公式 sin(2x)=2sin(x)cos(x)，再将右端移至左端。"
        },
        {
          "step": 2,
          "expression": "cos(x)(2sin(x)−1)=0 ⇔ cos(x)=0 或 sin(x)=1/2",
          "justification": "提取公因式 cos(x)，并使用实数乘积为零的性质；此过程无需除以可能为零的 cos(x)。"
        },
        {
          "step": 3,
          "expression": "cos(x)=0，0≤x<2π ⇒ x=π/2 或 x=3π/2",
          "justification": "在一个周期内，单位圆上横坐标为零的两个角分别为 π/2 和 3π/2。"
        },
        {
          "step": 4,
          "expression": "sin(x)=1/2，0≤x<2π ⇒ x=π/6 或 x=5π/6",
          "justification": "参考角为 π/6，且正弦为正的角位于第一、第二象限。"
        },
        {
          "step": 5,
          "expression": "x∈{π/6，π/2，5π/6，3π/2}",
          "justification": "合并两个分支的解；四个值均属于指定区间，且两个分支已覆盖乘积为零的全部情形。"
        }
      ],
      "answer": "x=π/6、π/2、5π/6 或 3π/2。",
      "conditions": ["0≤x<2π"]
    },
    "verification": {
      "status": "passed",
      "checks": [
        {
          "name": "代回原方程",
          "status": "passed",
          "details": "x=π/6 时，两端均为 √3/2；x=π/2 时，两端均为 0；x=5π/6 时，两端均为 −√3/2；x=3π/2 时，两端均为 0。"
        },
        {
          "name": "区间与解的完整性检查",
          "status": "passed",
          "details": "四个解均在 [0,2π) 内。原方程经恒等变形等价于 cos(x)(2sin(x)−1)=0，两个因式为零的情形均已穷尽；端点 x=0 不满足原方程，2π 不属于指定区间。"
        }
      ],
      "issues": []
    },
    "teaching_notes": {
      "key_insight": "展开二倍角后保留 cos(x) 为零的分支，用因式分解避免漏解。",
      "difficult_steps": ["将乘积为零拆分为两个方程。", "根据象限找全指定区间内的特殊角。"],
      "common_mistakes": ["直接约去 cos(x)，漏掉 π/2 和 3π/2。", "求 sin(x)=1/2 时只写 π/6，漏掉第二象限的 5π/6。"],
      "prerequisite_explanations": ["除以一个含未知数的式子前，必须考虑该式子为零的情况。", "单位圆上，点的横坐标为余弦值，纵坐标为正弦值。"],
      "alternative_method": null,
      "follow_up_exercise_suggestion": null
    }
  }
}

